<?php

declare(strict_types=1);

namespace Capell\Core\Contracts\Extensions;

use Capell\Core\Data\Permissions\PermissionSetData;

/**
 * A package's typed permission surface. Admin seeds these permissions and
 * grants each one's default roles once; the package's gate checks may only
 * name abilities declared here, listed in capell.json, or generated by Shield
 * for the Filament screens it ships.
 */
interface DeclaresPermissions
{
    public function permissions(): PermissionSetData;
}
